opaque mandatory<300..400>;
      /* length field is 2 bytes, cannot be empty */
uint16 longer<0..800>;
      /* zero to 400 16-bit unsigned integers */

struct {
    T1 f1;
    T2 f2;
    ...
    Tn fn;
} [[T]];

struct {
    T1 f1;
    T2 f2;
    ....
    Tn fn;
     select (E) {
         case e1: Te1;
         case e2: Te2;
         case e3: case e4: Te3;
         ....
         case en: Ten;
     } [[fv]];
} [[Tv]];

struct {
    uint16 number;
    opaque string<0..10>; /* variable length */
} V1;

struct {
    uint32 number;
    opaque string[10];    /* fixed length */
} V2;

struct {
    select (VariantTag) { /* value of selector is implicit */
        case apple:
          V1;   /* VariantBody, tag = apple */
        case orange:
        case banana:
          V2;   /* VariantBody, tag = orange or banana */
    } variant_body;       /* optional label on variant */
} VariantRecord;

struct {
   SignatureAndHashAlgorithm algorithm;
   opaque signature<0..2^16-1>;
} DigitallySigned;

Dss-Sig-Value ::= SEQUENCE {
    r INTEGER,
    s INTEGER
}

struct {
    uint8 field1;
    uint8 field2;
    digitally-signed opaque {
      uint8 field3<0..255>;
      uint8 field4;
    };
} UserType;

struct {
    uint8 f1;
    uint8 f2;
} Example1;

struct {
    uint8 major;
    uint8 minor;
} ProtocolVersion;

enum {
    reserved(20), alert(21), handshake(22),
    application_data(23), (255)
} ContentType;

struct {
    ContentType type;
    ProtocolVersion version;
    uint16 length;
    opaque fragment[TLSPlaintext.length];
} TLSPlaintext;

struct {
    ContentType type;
    ProtocolVersion version;
    uint16 length;
    opaque nonce_explicit[SecurityParameters.record_iv_length];
    aead-ciphered struct {
       opaque content[TLSPlaintext.length];
    } fragment;
} TLSCiphertext;

struct {
    AlertLevel level;
    AlertDescription description;
} Alert;

ClientHello
ClientKeyShare            -------->
                                                ServerHello
                                             ServerKeyShare
                                     {EncryptedExtensions*}
                                             {Certificate*}
                                      {CertificateRequest*}
                                       {CertificateVerify*}
                          <--------              {Finished}
{Certificate*}
{CertificateVerify*}
{Finished}                -------->
[Application Data]        <------->      [Application Data]

ClientHello
ClientKeyShare            -------->
                                                ServerHello
                                             ServerKeyShare
                                     {EncryptedExtensions*}
                                             {Certificate*}
                                      {CertificateRequest*}
                                       {CertificateVerify*}
                          <--------              {Finished}
{Certificate*}
{CertificateVerify*}
{Finished}                -------->
[Application Data]        <------->     [Application Data]

struct {
    HandshakeType msg_type;    /* handshake type */
    uint24 length;             /* bytes in message */
    select (HandshakeType) {
        case client_hello:        ClientHello;
        case client_key_share:    ClientKeyShare;
        case server_hello:        ServerHello;
        case hello_retry_request: HelloRetryRequest;
        case server_key_share:    ServerKeyShare;
        case certificate:         Certificate;
        case certificate_request: CertificateRequest;
        case certificate_verify:  CertificateVerify;
        case finished:            Finished;
    } body;
} Handshake;

struct {
    opaque random_bytes[32];
} Random;

struct {
    ProtocolVersion client_version;
    Random random;
    SessionID session_id;
    CipherSuite cipher_suites<2..2^16-2>;
    CompressionMethod compression_methods<1..2^8-1>;
    select (extensions_present) {
        case false:
            struct {};
        case true:
            Extension extensions<0..2^16-1>;
    };
} ClientHello;

struct {
    NamedGroup group;
    opaque key_exchange<1..2^16-1>;
} ClientKeyShareOffer;

struct {
    ClientKeyShareOffer offers<0..2^16-1>;
} ClientKeyShare;

struct {
    ProtocolVersion server_version;
    Random random;
    SessionID session_id;
    CipherSuite cipher_suite;
    select (extensions_present) {
        case false:
            struct {};
        case true:
            Extension extensions<0..2^16-1>;
    };
} ServerHello;

struct {
    ProtocolVersion server_version;
    CipherSuite cipher_suite;
    NamedGroup selected_group;
    Extension extensions<0..2^16-1>;
} HelloRetryRequest;

struct {
    ExtensionType extension_type;
    opaque extension_data<0..2^16-1>;
} Extension;

enum {
    signature_algorithms(13), early_data(TBD), (65535)
} ExtensionType;

enum {
    none(0), md5(1), sha1(2), sha224(3), sha256(4), sha384(5),
    sha512(6), (255)
} HashAlgorithm;

struct {
      HashAlgorithm hash;
      SignatureAlgorithm signature;
} SignatureAndHashAlgorithm;

struct {
    NamedGroup named_group_list<1..2^16-1>
} NamedGroupList;

struct {
  TLSCipherText messages<5 .. 2^24-1>;
} EarlyDataExtension;

struct {
  NamedGroup group;
  opaque key_exchange<1..2^16-1>;
} ServerKeyShare;

struct {
    Extension extensions<0..2^16-1>;
} EncryptedExtensions;

struct {
    ASN1Cert certificate_list<0..2^24-1>;
} Certificate;

enum {
    rsa_sign(1), dss_sign(2), rsa_fixed_dh(3), dss_fixed_dh(4),
    rsa_ephemeral_dh_RESERVED(5), dss_ephemeral_dh_RESERVED(6),
    fortezza_dms_RESERVED(20), (255)
} ClientCertificateType;

struct {
    ClientCertificateType certificate_types<1..2^8-1>;
    SignatureAndHashAlgorithm
      supported_signature_algorithms<2..2^16-2>;
    DistinguishedName certificate_authorities<0..2^16-1>;
} CertificateRequest;

struct {
     digitally-signed struct {
         opaque handshake_messages_hash[hash_length];
     }
} CertificateVerify;

struct {
    opaque verify_data[verify_data_length];
} Finished;

struct {
    HandshakeType msg_type;
    uint24 length;
    select (HandshakeType) {
        case hello_request:       HelloRequest;
        case client_hello:        ClientHello;
        case server_hello:        ServerHello;
        case hello_retry_request: HelloRetryRequest;
        case certificate:         Certificate;
        case server_key_share:    ServerKeyShare;
        case certificate_request: CertificateRequest;
        case server_hello_done:   ServerHelloDone;
        case certificate_verify:  CertificateVerify;
        case client_key_share:    ClientKeyShare;
        case finished:            Finished;
    } body;
} Handshake;

struct {
    ProtocolVersion client_version;
    Random random;
    SessionID session_id;
    CipherSuite cipher_suites<2..2^16-2>;
    CompressionMethod compression_methods<1..2^8-1>;
    select (extensions_present) {
        case false:

            struct {};
        case true:
            Extension extensions<0..2^16-1>;
    };
} ClientHello;

struct {
    ProtocolVersion server_version;
    Random random;
    SessionID session_id;
    CipherSuite cipher_suite;
    select (extensions_present) {
        case false:
            struct {};
        case true:
            Extension extensions<0..2^16-1>;
    };
} ServerHello;

